+import { getEvents } from "./jobs.ts";
+
+export interface EventStreamResponse {
+  events: Array<{
+    id: string;
+    eventType: string;
+    createdAt: string;
+    data?: Record<string, unknown>;
+  }>;
+  nextCursor: string;
+}
+
+export const handleEventStream = async (
+  queryParams: Record<string, string>,
+): Promise<EventStreamResponse> => {
+  const since = queryParams.since;
+  const limit = Math.min(parseInt(queryParams.limit || "100"), 1000);
+
+  const events = await getEvents(since, limit);
+
+  const nextCursor =
+    events.length > 0 ? events[events.length - 1].createdAt.toISOString() : since || "";
+
+  return {
+    events: events.map((e) => ({
+      id: e.id,
+      eventType: e.eventType,
+      createdAt: e.createdAt.toISOString(),
+      data: e.data,
+    })),
+    nextCursor,
+  };
+};
